<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import {computed,ref,watch} from 'vue';
import {Search,Star,RefreshCw,ChevronLeft,ChevronRight,Download,Upload,X,Plus,Pencil,Trash2,ListFilter,ArrowUp,ArrowDown,History} from 'lucide-vue-next';
import {useStudio,api} from '../store';
import {filterLibraryTags} from '../../shared/tag-library.mjs';
const emit=defineEmits(['select']),s=useStudio();
const category=ref('all'),group=ref('all'),search=ref(''),page=ref(0),refreshing=ref(false),customZh=ref(''),customEn=ref('');
const importInput=ref(),pendingImport=ref(null),importMode=ref('merge'),transferring=ref(false),exportFormat=ref('json');
const editMode=ref(false),selecting=ref(false),selected=ref([]),editor=ref(null),confirmDelete=ref(null),history=ref(null);
const moveGroups=computed(()=>categories.value.find(c=>c.p_uuid===editor.value?.categoryId)?.groups||[]),moveReferences=computed(()=>s.tags.filter(t=>t.groupId===editor.value?.groupId&&t.id!==editor.value?.id));
const categories=computed(()=>s.tagLibrary?.groups||[]),current=computed(()=>categories.value.find(c=>c.p_uuid===category.value)),subgroups=computed(()=>current.value?.groups||[]),favorites=computed(()=>s.config.favoriteTags||[]);
const tags=computed(()=>[...s.tags,...(s.config.customTags||[]).map((t,i)=>({...t,id:'custom-'+i,categoryId:'custom',groupId:'custom',group:'自定义'}))]);
const filtered=computed(()=>filterLibraryTags(tags.value,{category:category.value,group:group.value,search:search.value,favorites:favorites.value}));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/80))),visible=computed(()=>filtered.value.slice(page.value*80,(page.value+1)*80));
watch(category,()=>{group.value='all';page.value=0;},{flush:'sync'});watch([group,search],()=>page.value=0);watch(pages,total=>page.value=Math.min(page.value,total-1));
function favorite(tag){const list=s.config.favoriteTags||(s.config.favoriteTags=[]),i=list.indexOf(tag.en);i>=0?list.splice(i,1):list.push(tag.en);}
async function manage(request){transferring.value=true;try{const result=await api('tag-library/manage',request);s.tagLibrary=result.library;s.tags=result.library.tags;s.config.customTags=result.personal.customTags;selected.value=selected.value.filter(id=>s.tags.some(tag=>tag.id===id));if(!categories.value.some(c=>c.p_uuid===category.value)&&!['all','favorites'].includes(category.value))category.value='all';if(!subgroups.value.some(g=>g.g_uuid===group.value))group.value='all';s.notify('词库已保存，所有入口已同步');return result;}finally{transferring.value=false;}}
async function addCustom(){if(!customEn.value.trim()||!customZh.value.trim())return;let cat=categories.value.find(c=>c.name==='自定义');if(!cat){await manage({action:'category.add',name:'自定义',color:'#7954d9'});cat=categories.value.find(c=>c.name==='自定义');}let child=cat.groups[0];if(!child){await manage({action:'group.add',categoryId:cat.p_uuid,name:'自定义标签',color:'#7954d9'});child=categories.value.find(c=>c.p_uuid===cat.p_uuid).groups[0];}await manage({action:'tag.add',groupId:child.g_uuid,text:customEn.value.trim(),desc:customZh.value.trim(),color:'#7954d9'});customEn.value='';customZh.value='';category.value=cat.p_uuid;group.value=child.g_uuid;}
function openEditor(kind,item=null){if(kind==='group'&&!current.value){s.notify('请先选择一个分类');return;}if(kind==='tag'&&!item&&group.value==='all'){s.notify('请先选择具体分组，再添加标签');return;}editor.value={kind,id:item?.p_uuid&&kind==='category'?item.p_uuid:item?.g_uuid&&kind==='group'?item.g_uuid:item?.id||'',name:item?.name||'',text:item?.en||'',desc:item?.zh||'',color:item?.color||'#7954d9',categoryId:item?.categoryId||category.value,groupId:item?.groupId||group.value,position:'start',referenceId:''};}
async function saveEditor(){const e=editor.value;const result=await manage({action:e.kind+'.'+(e.kind==='move'?'move':e.id?'edit':'add'),...e,...(e.kind==='move'?{action:'tag.move'}:{})});if(e.kind==='category'&&!e.id){const item=result.library.groups.find(c=>c.name===e.name);if(item)category.value=item.p_uuid;}editor.value=null;}
function askDelete(kind,item){confirmDelete.value={action:kind+'.delete',id:kind==='category'?item.p_uuid:kind==='group'?item.g_uuid:item.id,title:kind==='tag'?(item.zh||item.en):item.name};}
async function removeSelected(){await manage(confirmDelete.value);confirmDelete.value=null;}
function toggleSelected(id){selected.value=selected.value.includes(id)?selected.value.filter(t=>t!==id):[...selected.value,id];}
const allVisibleSelected=computed(()=>visible.value.length>0&&visible.value.every(t=>selected.value.includes(t.id)));
function selectPage(){const ids=new Set(visible.value.map(t=>t.id));selected.value=allVisibleSelected.value?selected.value.filter(id=>!ids.has(id)):[...new Set([...selected.value,...ids])];}
async function shareSelected(){const file=await api('tag-library/share',{ids:selected.value,format:exportFormat.value});const result=await s.exportFile(file.name,new Blob([file.contents]));if(result!==false)s.notify('已导出所选标签及所属分类、分组');}
async function openHistory(){history.value=await api('tag-library/backups');}
async function restoreBackup(item){const preview=await api('tag-library/backups/preview',{id:item.id});history.value=null;pendingImport.value={...preview,name:'修改前的备份 · '+new Date(item.created).toLocaleString()};importMode.value='replace';}
async function refresh(){refreshing.value=true;try{const result=await s.refreshTagLibrary();s.notify(result.warning||`词库已刷新 · ${result.counts.tags} 个标签`);}finally{refreshing.value=false;}}
async function exportAll(){transferring.value=true;try{const file=await api('tag-library/export',{format:exportFormat.value});const saved=await s.exportFile(file.name,new Blob([file.contents],{type:exportFormat.value==='sql'?'application/sql':'application/json'}));if(saved!==false)s.notify('完整词库已导出'+(saved?.path?'：'+saved.path:''));}finally{transferring.value=false;}}
async function previewFile(event){const file=event.target.files?.[0];if(!file)return;transferring.value=true;try{if(file.size>16*1024*1024)throw Error('词库文件不能超过 16 MB');const preview=await api('tag-library/import/preview',{format:file.name.toLowerCase().endsWith('.sql')?'sql':'json',contents:await file.text()});pendingImport.value={...preview,name:file.name};importMode.value='merge';}finally{transferring.value=false;event.target.value='';}}
async function importAll(){transferring.value=true;try{const result=await api('tag-library/import',{token:pendingImport.value.token,mode:importMode.value});s.tagLibrary=result.library;s.tags=result.library.tags;s.config.customTags=result.personal.customTags;s.config.favoriteTags=result.personal.favoriteTags;pendingImport.value=null;category.value='all';group.value='all';page.value=0;s.notify(`导入完成 · ${result.library.counts.tags} 个标签，原词库已自动备份`);}finally{transferring.value=false;}}
</script>
<template>
<section class="tag-browser library-tag-browser" :aria-label="ui(&quot;完整标签词库&quot;)">
 <div class="library-library-heading"><strong>{{ui("完整标签词库")}}</strong><span>{{ui(s.tagLibrary?.counts.categories)}}{{ui(" 个分类 · ")}}{{ui(s.tagLibrary?.counts.groups)}}{{ui(" 个分组 · ")}}{{ui(s.tagLibrary?.counts.tags)}}{{ui(" 个标签")}}</span><button class="quiet" :disabled="refreshing" :aria-busy="refreshing" @click="s.action(refresh)"><RefreshCw :size="15"/>{{ui("刷新词库")}}</button></div>
 <div class="library-library-transfer"><div class="tag-export-format segmented" role="group" :aria-label="ui(&quot;词库导出格式&quot;)"><button :class="{active:exportFormat==='json'}" :title="ui(&quot;JSON：包括自定义标签与收藏&quot;)" @click="exportFormat='json'">JSON</button><button :class="{active:exportFormat==='sql'}" :title="ui(&quot;SQL：完整词库交换文件&quot;)" @click="exportFormat='sql'">SQL</button></div><button class="secondary" :disabled="transferring" @click="s.action(exportAll)"><Download :size="15"/>{{ui("导出全部标签")}}</button><button class="secondary" :disabled="transferring" @click="importInput.click()"><Upload :size="15"/>{{ui("导入标签词库")}}</button><button class="quiet" @click="s.action(openHistory)"><History :size="15"/>{{ui("修改历史")}}</button><input ref="importInput" type="file" accept=".json,.sql" class="hidden" @change="s.action(()=>previewFile($event))"/></div>
 <p v-if="s.tagLibrary?.warning" class="error-note">{{ui(s.tagLibrary.warning)}}</p>
 <div class="search-input"><Search :size="16"/><input v-model="search" :placeholder="ui(&quot;搜索中文或英文标签、分类、分组&quot;)" :aria-label="ui(&quot;搜索完整标签词库&quot;)"/></div>
 <div class="category-tabs library-categories" :aria-label="ui(&quot;标签分类&quot;)">
  <button :class="{active:category==='all'}" @click="category='all'">{{ui("全部")}}</button><button :class="{active:category==='favorites'}" @click="category='favorites'">{{ui("收藏")}}</button>
  <div v-for="item in categories" :key="item.p_uuid" class="library-category-item"><button :class="{active:category===item.p_uuid}" @click="category=item.p_uuid">{{ui(item.name)}}</button><span v-if="editMode" class="library-inline-actions"><button :aria-label="ui('编辑分类 '+item.name)" @click="openEditor('category',item)"><Pencil :size="13"/></button><button :aria-label="ui('分类前移 '+item.name)" @click="s.action(()=>manage({action:'category.move',id:item.p_uuid,offset:-1}))"><ArrowUp :size="13"/></button><button :aria-label="ui('分类后移 '+item.name)" @click="s.action(()=>manage({action:'category.move',id:item.p_uuid,offset:1}))"><ArrowDown :size="13"/></button><button :aria-label="ui('删除分类 '+item.name)" @click="askDelete('category',item)"><Trash2 :size="13"/></button></span></div>
  <button v-if="s.config.customTags?.length" :class="{active:category==='custom'}" @click="category='custom'">{{ui("自定义")}}</button><button class="secondary" @click="openEditor('category')"><Plus :size="15"/>{{ui("添加分类")}}</button><label class="inline-check"><input type="checkbox" v-model="editMode"/>{{ui("编辑模式")}}</label>
 </div>
 <div v-if="current" class="category-tabs library-subgroups" :aria-label="ui(&quot;标签分组&quot;)"><button :class="{active:group==='all'}" @click="group='all'">{{ui("全部分组")}}</button><div v-for="item in subgroups" :key="item.g_uuid" class="library-category-item"><button :class="{active:group===item.g_uuid}" @click="group=item.g_uuid">{{ui(item.name)}} <small>{{ui(item.tags.length)}}</small></button><span v-if="editMode" class="library-inline-actions"><button :aria-label="ui('编辑分组 '+item.name)" @click="openEditor('group',item)"><Pencil :size="13"/></button><button :aria-label="ui('分组前移 '+item.name)" @click="s.action(()=>manage({action:'group.move',id:item.g_uuid,offset:-1}))"><ArrowUp :size="13"/></button><button :aria-label="ui('分组后移 '+item.name)" @click="s.action(()=>manage({action:'group.move',id:item.g_uuid,offset:1}))"><ArrowDown :size="13"/></button><button :aria-label="ui('删除分组 '+item.name)" @click="askDelete('group',item)"><Trash2 :size="13"/></button></span></div><button class="secondary" @click="openEditor('group')"><Plus :size="15"/>{{ui("添加分组")}}</button></div>
 <div class="library-result-heading"><strong>{{ui(group==='all'?(current?.name||'标签'):subgroups.find(g=>g.g_uuid===group)?.name)}}</strong><span>{{ui("共 ")}}{{ui(filtered.length)}}{{ui(" 个 · ")}}{{ui(page*80+(filtered.length?1:0))}}–{{ui(Math.min((page+1)*80,filtered.length))}}</span><div class="button-row"><button class="secondary" :disabled="!current||group==='all'" @click="openEditor('tag')"><Plus :size="15"/>{{ui("添加标签")}}</button><button class="secondary" @click="selecting=true">{{ui("批量分享标签")}}</button><button class="secondary danger" @click="selecting=true">{{ui("批量删除")}}</button></div></div>
 <div v-if="selecting" class="library-selection"><label><input type="checkbox" :checked="allVisibleSelected" @change="selectPage"/>{{ui("全选本页标签")}}</label><span>{{ui("已选 ")}}{{ui(selected.length)}}{{ui(" 个")}}</span><button class="quiet" @click="selected=filtered.map(t=>t.id)">{{ui("选择全部结果")}}</button><button class="secondary" :disabled="!selected.length||transferring" @click="s.action(shareSelected)">{{ui("分享所选")}}</button><button class="secondary danger" :disabled="!selected.length||transferring" @click="confirmDelete={action:'tag.deleteMany',ids:[...selected],title:'所选 '+selected.length+' 个标签'}">{{ui("删除所选标签")}}</button><button class="quiet" @click="selecting=false;selected=[]">{{ui("退出多选")}}</button></div>
 <div class="tag-grid"><div v-for="tag in visible" :key="tag.id" class="tag-card library-manage-tag" :class="{selected:selected.includes(tag.id)}" tabindex="0"><label v-if="selecting" class="library-tag-check"><input type="checkbox" :checked="selected.includes(tag.id)" :aria-label="ui('选择标签 '+tag.en)" @change="toggleSelected(tag.id)"/></label><button class="library-tag-pick" :title="ui((tag.zh||tag.en)+' · '+tag.en+' / '+tag.category+' / '+tag.group)" @click="selecting?toggleSelected(tag.id):emit('select',tag)"><strong>{{ui(tag.zh||tag.en)}}</strong><small>{{ui(tag.en)}}</small></button><button class="library-favorite" :class="{starred:favorites.includes(tag.en)}" :aria-label="ui('收藏标签 '+tag.en)" @click="favorite(tag)"><Star :size="14"/></button><span class="library-tag-tools"><button :aria-label="ui('移动标签 '+tag.en)" :title="ui('移动标签 '+tag.en)" @click="openEditor('move',tag)"><ListFilter :size="14"/></button><button :aria-label="ui('编辑标签 '+tag.en)" :title="ui('编辑标签 '+tag.en)" @click="openEditor('tag',tag)"><Pencil :size="14"/></button><button :aria-label="ui('删除标签 '+tag.en)" :title="ui('删除标签 '+tag.en)" @click="askDelete('tag',tag)"><Trash2 :size="14"/></button></span></div></div>
 <p v-if="!filtered.length" class="muted">{{ui("没有符合条件的标签")}}</p><div v-if="pages>1" class="pagination"><button class="secondary" :disabled="page===0" @click="page--"><ChevronLeft :size="16"/>{{ui("上一页")}}</button><label>{{ui("第 ")}}<select v-model.number="page" :aria-label="ui(&quot;标签页码&quot;)"><option v-for="n in pages" :value="n-1">{{ui(n)}}</option></select> / {{ui(pages)}}{{ui(" 页")}}</label><button class="secondary" :disabled="page+1>=pages" @click="page++">{{ui("下一页")}}<ChevronRight :size="16"/></button></div>
 <div class="custom-tag"><input v-model="customZh" :placeholder="ui(&quot;自定义标签：中文&quot;)"/><input v-model="customEn" :placeholder="ui(&quot;英文标签&quot;)"/><button class="secondary" :disabled="transferring" @click="s.action(addCustom)">{{ui("添加到词库")}}</button></div>
 <div v-if="editor" class="modal-backdrop" @click.self="!transferring&&s.action(saveEditor)"><section class="modal" role="dialog" :aria-label="ui(&quot;编辑标签词库&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭词库编辑&quot;)" @click="editor=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui(editor.kind==='move'?'移动标签':(editor.id?'编辑':'添加')+({category:'分类',group:'分组',tag:'标签'}[editor.kind]))}}</h2></div>
  <template v-if="editor.kind==='move'"><label>{{ui("目标分类")}}<select v-model="editor.categoryId" @change="editor.groupId=moveGroups[0]?.g_uuid||'';editor.referenceId=''" :aria-label="ui(&quot;移动目标分类&quot;)"><option v-for="c in categories" :value="c.p_uuid">{{ui(c.name)}}</option></select></label><label>{{ui("目标分组")}}<select v-model="editor.groupId" @change="editor.referenceId=''" :aria-label="ui(&quot;移动目标分组&quot;)"><option v-for="g in moveGroups" :value="g.g_uuid">{{ui(g.name)}}</option></select></label><label>{{ui("移动位置")}}<select v-model="editor.position" :aria-label="ui(&quot;标签移动位置&quot;)"><option value="start">{{ui("分组最前")}}</option><option value="end">{{ui("分组最后")}}</option><option value="before">{{ui("参考标签之前")}}</option><option value="after">{{ui("参考标签之后")}}</option></select></label><label v-if="['before','after'].includes(editor.position)">{{ui("参考标签")}}<select v-model="editor.referenceId" :aria-label="ui(&quot;移动参考标签&quot;)"><option value="">{{ui("请选择")}}</option><option v-for="tag in moveReferences" :value="tag.id">{{ui(tag.zh)}} · {{ui(tag.en)}}</option></select></label></template>
  <template v-else-if="editor.kind==='tag'"><label>{{ui("英文标签")}}<input v-model="editor.text" :aria-label="ui(&quot;词库英文标签&quot;)" maxlength="2000"/></label><label>{{ui("中文说明")}}<input v-model="editor.desc" :aria-label="ui(&quot;词库中文说明&quot;)" maxlength="2000"/></label></template><label v-else>{{ui("名称")}}<input v-model="editor.name" :aria-label="ui(&quot;词库项目名称&quot;)" maxlength="200"/></label><label v-if="editor.kind!=='move'">{{ui("颜色")}}<input v-model="editor.color" :aria-label="ui(&quot;词库项目颜色&quot;)" :placeholder="ui(&quot;#7954d9 或 rgba(255,123,2,.4)&quot;)"/></label><div class="button-row"><button class="secondary" @click="editor=null">{{ui("取消")}}</button><button class="primary" :disabled="transferring" @click="s.action(saveEditor)">{{ui(transferring?'保存中…':'保存词库修改')}}</button></div></section></div>
 <div v-if="confirmDelete" class="modal-backdrop" @click.self="!transferring&&(confirmDelete=null)"><section class="modal" role="dialog" :aria-label="ui(&quot;删除词库内容&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭词库删除确认&quot;)" @click="confirmDelete=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui("删除词库内容")}}</h2></div><p>{{ui("删除“")}}{{ui(confirmDelete.title)}}{{ui("”？分类和分组内的标签也会一起删除。")}}</p><p class="muted">{{ui("已加入提示词的文字会保留。可在“修改历史”中恢复删除前的词库。")}}</p><div class="button-row"><button class="secondary" @click="confirmDelete=null">{{ui("取消")}}</button><button class="primary" :disabled="transferring" @click="s.action(removeSelected)">{{ui("确认删除词库内容")}}</button></div></section></div>
 <div v-if="history" class="modal-backdrop" @click.self="history=null"><section class="modal" role="dialog" :aria-label="ui(&quot;词库修改历史&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭词库修改历史&quot;)" @click="history=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui("词库修改历史")}}</h2></div><p class="muted">{{ui("每次修改前自动备份。恢复前还会保留当前词库。")}}</p><p v-if="!history.length">{{ui("暂无修改记录")}}</p><div v-for="item in history" :key="item.id" class="library-backup-row"><span>{{ui(new Date(item.created).toLocaleString())}}</span><button class="secondary" @click="s.action(()=>restoreBackup(item))">{{ui("恢复此备份")}}</button></div></section></div>
 <div v-if="pendingImport" class="modal-backdrop" @click.self="!transferring&&(pendingImport=null)"><section class="modal" role="dialog" :aria-label="ui(&quot;导入完整标签词库&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭词库导入&quot;)" @click="pendingImport=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui("导入标签词库")}}</h2></div><p>{{ui(pendingImport.name)}}</p><p>{{ui(pendingImport.counts.categories)}}{{ui(" 个分类 · ")}}{{ui(pendingImport.counts.groups)}}{{ui(" 个分组 · ")}}{{ui(pendingImport.counts.tags)}}{{ui(" 个标签")}}<span v-if="pendingImport.personalTags"> · {{ui(pendingImport.personalTags)}}{{ui(" 个自定义标签")}}</span></p><label>{{ui("导入方式")}}<select v-model="importMode" :aria-label="ui(&quot;标签导入方式&quot;)"><option value="merge">{{ui("合并到现有词库（保留现有标签）")}}</option><option value="replace">{{ui("替换整个词库（自动备份原词库）")}}</option></select></label><p class="muted">{{ui("分类、分组、中英文内容和顺序一起导入。原词库自动备份，可在修改历史中恢复。")}}</p><div class="button-row"><button class="secondary" @click="pendingImport=null">{{ui("取消")}}</button><button class="primary" :disabled="transferring" @click="s.action(importAll)">{{ui(transferring?'正在导入…':'确认导入词库')}}</button></div></section></div>
</section></template>
